import { getServerSession } from 'next-auth';
import { getAllLibraryFiles } from '@/lib/googleDrive';
import { getCachedLibrary, setCachedLibrary } from '@/lib/libraryCache';
import authOptions from '@/lib/auth';
import type { BookEntry } from '@/types/books';

export async function GET(request: Request) {
  const session = await getServerSession(authOptions);

  if (!session?.accessToken) {
    return Response.json({ error: 'Unauthorized' }, { status: 401 });
  }

  const email = session.user?.email ?? undefined;

  try {
    const url = new URL(request.url);
    const forceRefresh = url.searchParams.get('refresh') === '1';

    if (!forceRefresh) {
      const cached = await getCachedLibrary(session.accessToken, email);
      if (cached) {
        return Response.json(cached);
      }
    }

    const books: BookEntry[] = await getAllLibraryFiles(session.accessToken);
    await setCachedLibrary(session.accessToken, books, email);
    return Response.json(books);
  } catch (error) {
    console.error('Failed to fetch library:', error);
    return Response.json(
      { error: 'Failed to fetch library' },
      { status: 500 }
    );
  }
}
import { type NextAuthOptions, type DefaultSession } from 'next-auth';
import GoogleProvider from 'next-auth/providers/google';

/**
 * Module augmentation to add accessToken and error to session
 */
declare module 'next-auth' {
  interface Session extends DefaultSession {
    accessToken?: string;
    error?: string;
  }
}

declare module 'next-auth/jwt' {
  interface JWT {
    accessToken?: string;
    refreshToken?: string;
    expiresAt?: number;
    error?: string;
  }
}

export const authOptions: NextAuthOptions = {
  providers: [
    GoogleProvider({
      clientId: process.env.GOOGLE_CLIENT_ID!,
      clientSecret: [REDACTED_SECRET]
      authorization: {
        params: {
          access_type: 'offline',
          prompt: 'consent',
          scope: 'openid email profile https://www.googleapis.com/auth/drive',
        },
      },
    }),
  ],
  session: {
    strategy: 'jwt',
  },
  callbacks: {
    async jwt({ token, account }) {
      if (account) {
        token.accessToken = [REDACTED_SECRET]
        token.refreshToken = [REDACTED_SECRET]
        token.expiresAt = (account.expires_at ?? 0) * 1000;
      }

      if (token.expiresAt && Date.now() >= token.expiresAt) {
        if (token.refreshToken) {
          try {
            const response = await fetch('https://oauth2.googleapis.com/token', {
              method: 'POST',
              headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
              body: new URLSearchParams({
                client_id: process.env.GOOGLE_CLIENT_ID!,
                client_secret: [REDACTED_SECRET]
                grant_type: 'refresh_token',
                refresh_token: [REDACTED_SECRET]
              }).toString(),
            });

            if (response.ok) {
              const refreshedTokens = await response.json();
              token.accessToken = [REDACTED_SECRET]
              token.expiresAt = refreshedTokens.expires_in
                ? Date.now() + refreshedTokens.expires_in * 1000
                : token.expiresAt;
              if (refreshedTokens.refresh_token) {
                token.refreshToken = [REDACTED_SECRET]
              }
              token.error = undefined;
            } else {
              token.error = 'RefreshAccessTokenError';
            }
          } catch {
            token.error = 'RefreshAccessTokenError';
          }
        }
      }

      return token;
    },
    async session({ session, token }) {
      session.accessToken = [REDACTED_SECRET]
      session.error = token.error;
      return session;
    },
  },
  pages: {
    signIn: '/',
  },
};

export default authOptions;

