                  allowFullScreen
                  onError={() => setVideoError(true)}
                  className="bg-black"
                />
              ) : (
                <div className="aspect-video bg-slate-950 flex items-center justify-center">
                  <p className="text-slate-400">Invalid YouTube URL</p>
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

